/// Trip waypoint + two-party security-confirmation models over the live
/// `trip_waypoints` / `security_confirmations` tables (migration
/// 20260726090000). Waypoints are generated by `auto_generate_trip_waypoints`
/// as MG → WB → LP → WB → MG → drop-off (sequence 1..6).
enum WaypointType {
  mainGate,
  weighbridge,
  loadingPoint,
  dropOff;

  /// The exact string persisted in `trip_waypoints.location_type`.
  String get wire {
    switch (this) {
      case WaypointType.mainGate:
        return 'main_gate';
      case WaypointType.weighbridge:
        return 'weighbridge';
      case WaypointType.loadingPoint:
        return 'loading_point';
      case WaypointType.dropOff:
        return 'drop_off';
    }
  }

  String get label {
    switch (this) {
      case WaypointType.mainGate:
        return 'Main Gate';
      case WaypointType.weighbridge:
        return 'Weighbridge';
      case WaypointType.loadingPoint:
        return 'Loading Point';
      case WaypointType.dropOff:
        return 'Drop-off';
    }
  }

  /// Tolerant parse per the repo's wire-enum rule — unknown wire values never
  /// crash the UI.
  static WaypointType parse(String? raw) {
    final normalized =
        (raw ?? '').trim().toLowerCase().replaceAll(RegExp(r'[\s-]+'), '_');
    for (final value in WaypointType.values) {
      if (value.wire == normalized) return value;
    }
    return WaypointType.dropOff;
  }
}

/// A row of `trip_waypoints` — one ordered stop of a trip's mine-nav sequence.
class TripWaypoint {
  final String id;
  final String tripId;
  final int sequenceOrder;
  final WaypointType locationType;
  final String name;
  final double latitude;
  final double longitude;
  final String address;
  final bool isCompleted;
  final DateTime? completedAt;
  final DateTime? createdAt;

  const TripWaypoint({
    required this.id,
    required this.tripId,
    required this.sequenceOrder,
    required this.locationType,
    this.name = '',
    this.latitude = 0,
    this.longitude = 0,
    this.address = '',
    this.isCompleted = false,
    this.completedAt,
    this.createdAt,
  });

  /// A (0,0) waypoint is a placeholder (unconfigured anchor / unset drop-off).
  bool get hasCoordinates => latitude != 0 || longitude != 0;

  /// First weighbridge visit = tare weigh; second = gross weigh (the
  /// `auto_generate_trip_waypoints` sequence contract).
  bool get isTareWeighbridge =>
      locationType == WaypointType.weighbridge && sequenceOrder == 2;
  bool get isGrossWeighbridge =>
      locationType == WaypointType.weighbridge && sequenceOrder == 4;

  factory TripWaypoint.fromJson(Map<String, dynamic> json) => TripWaypoint(
        id: '${json['id']}',
        tripId: '${json['trip_id']}',
        sequenceOrder: (json['sequence_order'] as num?)?.toInt() ?? 0,
        locationType: WaypointType.parse(json['location_type'] as String?),
        name: (json['name'] as String?) ?? '',
        latitude: (json['latitude'] as num?)?.toDouble() ?? 0,
        longitude: (json['longitude'] as num?)?.toDouble() ?? 0,
        address: (json['address'] as String?) ?? '',
        isCompleted: json['is_completed'] == true,
        completedAt: json['completed_at'] != null
            ? DateTime.tryParse('${json['completed_at']}')
            : null,
        createdAt: json['created_at'] != null
            ? DateTime.tryParse('${json['created_at']}')
            : null,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'trip_id': tripId,
        'sequence_order': sequenceOrder,
        'location_type': locationType.wire,
        'name': name,
        'latitude': latitude,
        'longitude': longitude,
        'address': address,
        'is_completed': isCompleted,
        'completed_at': completedAt?.toIso8601String(),
        if (createdAt != null) 'created_at': createdAt!.toIso8601String(),
      };
}

/// Which gate event a `security_confirmations` row confirms.
enum SecurityConfirmationType {
  arrival,
  exit;

  /// The exact string persisted in `security_confirmations.confirmation_type`.
  String get wire {
    switch (this) {
      case SecurityConfirmationType.arrival:
        return 'arrival';
      case SecurityConfirmationType.exit:
        return 'exit';
    }
  }

  String get label {
    switch (this) {
      case SecurityConfirmationType.arrival:
        return 'Gate arrival';
      case SecurityConfirmationType.exit:
        return 'Gate exit';
    }
  }

  /// Tolerant parse per the repo's wire-enum rule.
  static SecurityConfirmationType parse(String? raw) {
    final normalized = (raw ?? '').trim().toLowerCase();
    for (final value in SecurityConfirmationType.values) {
      if (value.wire == normalized) return value;
    }
    return SecurityConfirmationType.arrival;
  }
}

/// A row of `security_confirmations` — the two-party (driver + mine security)
/// gate confirmation for a trip. Additive to the `set_trip_status` lifecycle,
/// never a replacement for it.
class SecurityConfirmation {
  final String id;
  final String tripId;
  final SecurityConfirmationType confirmationType;
  final bool driverConfirmed;
  final bool securityConfirmed;
  final DateTime? driverConfirmedAt;
  final DateTime? securityConfirmedAt;
  final String? securityUserId;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  const SecurityConfirmation({
    required this.id,
    required this.tripId,
    required this.confirmationType,
    this.driverConfirmed = false,
    this.securityConfirmed = false,
    this.driverConfirmedAt,
    this.securityConfirmedAt,
    this.securityUserId,
    this.createdAt,
    this.updatedAt,
  });

  bool get isFullyConfirmed => driverConfirmed && securityConfirmed;

  factory SecurityConfirmation.fromJson(Map<String, dynamic> json) =>
      SecurityConfirmation(
        id: '${json['id']}',
        tripId: '${json['trip_id']}',
        confirmationType:
            SecurityConfirmationType.parse(json['confirmation_type'] as String?),
        driverConfirmed: json['driver_confirmed'] == true,
        securityConfirmed: json['security_confirmed'] == true,
        driverConfirmedAt: json['driver_confirmed_at'] != null
            ? DateTime.tryParse('${json['driver_confirmed_at']}')
            : null,
        securityConfirmedAt: json['security_confirmed_at'] != null
            ? DateTime.tryParse('${json['security_confirmed_at']}')
            : null,
        securityUserId: json['security_user_id'] as String?,
        createdAt: json['created_at'] != null
            ? DateTime.tryParse('${json['created_at']}')
            : null,
        updatedAt: json['updated_at'] != null
            ? DateTime.tryParse('${json['updated_at']}')
            : null,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'trip_id': tripId,
        'confirmation_type': confirmationType.wire,
        'driver_confirmed': driverConfirmed,
        'security_confirmed': securityConfirmed,
        'driver_confirmed_at': driverConfirmedAt?.toIso8601String(),
        'security_confirmed_at': securityConfirmedAt?.toIso8601String(),
        'security_user_id': securityUserId,
        if (createdAt != null) 'created_at': createdAt!.toIso8601String(),
        if (updatedAt != null) 'updated_at': updatedAt!.toIso8601String(),
      };
}
